package net.battlespades.player;
import java.util.*;
import net.battlespades.physics.MovementProfile;
import net.battlespades.protocol.*;
import net.battlespades.rules.GameRules;
/** Mode-scoped server/hardcore.py roles, immutable rule view and negotiated movement. */
public final class Hardcore {
    private Hardcore(){}
    public static final List<String> BASES=List.of("tdm","ctf","cctf","zom","vip","mh","tc","dia","dem","oc");
    public static final List<Integer> CLASSES=List.of(5,0,1,3,17),COMMON=List.of(5,2,72,25,26,30);
    public static boolean enabled(String code){return code.startsWith("hc_")&&BASES.contains(code.substring(3));}
    public static String base(String code){return enabled(code)?code.substring(3):code;}
    public static List<Integer> slot(int id,int slot){return switch(slot){case 0->List.of(11,33);case 1->switch(id){case 5->List.of(60,7,38,35);case 0->List.of(61,10);case 1->List.of(18,19);default->List.of(7,38,35,9,37,62);};case 2->id==1?List.of(17,53):List.of(17);case 3->id==3?List.of(59,21):id==17?List.of(51):List.of();case 5->COMMON;default->List.of();};}
    public static ClassCatalog.Selection normalize(int id,Collection<Integer> requested){if(id==4)return ClassCatalog.normalize(4,List.of(),List.of(),List.of(),4,List.of());if(!CLASSES.contains(id))id=5;var chosen=new LinkedHashSet<Integer>();chosen.add(5);for(int slot=0;slot<4;slot++){var options=slot(id,slot);if(!options.isEmpty())chosen.add(options.stream().filter(requested::contains).findFirst().orElse(options.getFirst()));}chosen.addAll(COMMON);return new ClassCatalog.Selection(id,List.copyOf(chosen),List.of(),List.of());}
    public static GameRules rules(GameRules source){var allowed=new HashSet<Integer>();for(var id:CLASSES)for(int slot=0;slot<7;slot++)allowed.addAll(slot(id,slot));var changes=new HashMap<String,Object>();for(var d:GameRules.definitions().values()){if(d.toolId()>=0)changes.put(d.key(),allowed.contains(d.toolId()));if(d.classId()>=0)changes.put(d.key(),CLASSES.contains(d.classId()));}changes.putAll(Map.ofEntries(Map.entry("RULE_ENABLE_GRAVESTONES",false),Map.entry("RULE_ENABLE_CORPSE_EXPLOSION",false),Map.entry("RULE_POINTS_FROM_TEABAGGING",true),Map.entry("RULE_ONE_HIT_KILL",false),Map.entry("RULE_CHARACTER_SPEED",1.),Map.entry("RULE_WEAPON_DAMAGE",1.),Map.entry("RULE_ENABLE_MINI_MAP",true),Map.entry("RULE_ENABLE_DEATH_CAM",true),Map.entry("RULE_ENABLE_SPECTATORS",true),Map.entry("RULE_ENABLE_COLOUR_PICKER",true),Map.entry("RULE_ENABLE_SNIPER_BEAM",false)));return source.overlay(changes);}
    public static double speed(int id){return switch(id){case 5,1,17->.80;case 0->.68;case 3->.76;default->1.;};}
    public static MovementProfile movement(int id,float scale,MovementProfile ordinary){return CLASSES.contains(id)?new MovementProfile(.7f*scale,1.05f*scale,.35f*scale,.77f,8,10,40,100,ordinary.waterDamage()==0?0:1,true):ordinary;}
    public static InitialInfo initial(InitialInfo p){var f=p.features();var features=new InitialInfo.Features(0,f.minimap(),f.sameTeamCollision(),f.maxDrawDistance(),f.colourPicker(),f.colourPalette(),f.deathcam(),f.sniperBeam(),f.spectator(),f.exposedTeamsOnMinimap(),f.numericHp(),"",f.beachZModifiable(),f.minimapHeightIcons(),f.fallOnWaterDamage());var loadouts=new ArrayList<InitialInfo.Loadout>();for(var id:CLASSES)for(int slot=0;slot<7;slot++)loadouts.add(new InitialInfo.Loadout(id,slot,slot(id,slot)));var rules=new ArrayList<>(p.customRules());rules.add(new InitialInfo.Rule("BATTLESPADES_HARDCORE","1"));rules.add(new InitialInfo.Rule("RULE_POINTS_FROM_TEABAGGING","ON"));return new InitialInfo(p.identity(),p.mode(),p.map(),features,p.blockWalletMultiplier(),p.blockHealthMultiplier(),p.disabledTools(),p.disabledClasses(),p.movementSpeedMultipliers(),p.ugcPrefabSets(),p.enablePlayerScore(),p.serverName(),p.groundColors(),loadouts,p.allowShootingHoldingIntel(),p.friendlyFire(),rules,0,p.ugcMode());}
    public static StateData state(StateData p,boolean zombie){return new StateData(p.playerId(),p.fogColor(),1,p.lighting(),p.timeScale(),p.scoreLimit(),p.modeType(),p.teamHeadcountType(),team(p.team1(),zombie?List.of(4):CLASSES,zombie&&p.team1().lockedClass()),team(p.team2(),CLASSES,zombie&&p.team2().lockedClass()),p.lockTeamSwap(),p.lockSpectatorSwap(),p.prefabs(),p.entities(),p.cameraPoints(),p.cameraRotations(),p.hasMapEnded());}
    private static StateData.Team team(StateData.Team t,List<Integer> classes,boolean locked){return new StateData.Team(t.name(),t.color(),t.score(),t.locked(),t.canSeeOther(),t.showScore(),t.showMaxScore(),t.infiniteBlocks(),locked,t.lockedScore(),classes);}
}
